/// @ingroup CAPI_IOT_CONNECTIVITY_MODULE
/// @brief Enumeration for IoTCon error code.
/// @since_tizen 3.0
/// @{
abstract class iotcon_error_e {
  /// < Successful
  static const int IOTCON_ERROR_NONE = 0;

  /// < I/O error
  static const int IOTCON_ERROR_IO_ERROR = -5;

  /// < Out of memory
  static const int IOTCON_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int IOTCON_ERROR_PERMISSION_DENIED = -13;

  /// < Not supported
  static const int IOTCON_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Invalid parameter
  static const int IOTCON_ERROR_INVALID_PARAMETER = -22;

  /// < No data available
  static const int IOTCON_ERROR_NO_DATA = -61;

  /// < Time out
  static const int IOTCON_ERROR_TIMEOUT = -1073741823;

  /// < IoTivity errors
  static const int IOTCON_ERROR_IOTIVITY = -29884415;

  /// < Representation errors
  static const int IOTCON_ERROR_REPRESENTATION = -29884414;

  /// < Invalid type
  static const int IOTCON_ERROR_INVALID_TYPE = -29884413;

  /// < Already
  static const int IOTCON_ERROR_ALREADY = -29884412;

  /// < System errors
  static const int IOTCON_ERROR_SYSTEM = -29884410;
}

