/// @brief The response handle.
/// @details @a iotcon_response_h is an opaque data structure to respond to client.
/// @a iotcon_response_h is a data type of server's response which consists of result, header options, query, representation.
/// @since_tizen 3.0
typedef iotcon_response_h = ffi.Pointer<icl_resource_response>;

/// @brief Enumeration for result of response.
/// @since_tizen 3.0
abstract class iotcon_response_result_e {
  /// < Indicates result of response for success
  static const int IOTCON_RESPONSE_OK = 0;

  /// < Indicates result of response for error
  static const int IOTCON_RESPONSE_ERROR = 1;

  /// < Indicates result of response for resource creation
  static const int IOTCON_RESPONSE_RESOURCE_CREATED = 2;

  /// < Indicates result of response for resource deletion
  static const int IOTCON_RESPONSE_RESOURCE_DELETED = 3;

  /// < Indicates result of response for resource change
  static const int IOTCON_RESPONSE_RESOURCE_CHANGED = 4;

  /// < Indicates result of response for slow resource
  static const int IOTCON_RESPONSE_SLOW = 5;

  /// < Indicates result of response for accessing unauthorized resource
  static const int IOTCON_RESPONSE_FORBIDDEN = 6;
}

/// @brief Enumeration for connectivities which can be held in a resource.
/// @remarks IOTCON_CONNECTIVITY_PREFER_UDP and IOTCON_CONNECTIVITY_PREFER_TCP should be mutually exclusive.
/// @remarks IOTCON_CONNECTIVITY_IPV4_ONLY and IOTCON_CONNECTIVITY_IPV6_ONLY should be mutually exclusive.
/// @since_tizen 3.0
abstract class iotcon_connectivity_type_e {
  /// < Indicates all connectivities
  static const int IOTCON_CONNECTIVITY_ALL = 0;

  /// < Indicates Internet Protocol connectivity
  static const int IOTCON_CONNECTIVITY_IP = 1;

  /// < It is related to IOTCON_CONNECTIVITY_IP, and it indicates UDP is preferred
  static const int IOTCON_CONNECTIVITY_PREFER_UDP = 65536;

  /// < It is related to IOTCON_CONNECTIVITY_IP, and it indicates TCP is preferred
  static const int IOTCON_CONNECTIVITY_PREFER_TCP = 131072;

  /// < When this bit is set with IOTCON_CONNECTIVITY_IP, resources are discovered for IPv4
  static const int IOTCON_CONNECTIVITY_IPV4_ONLY = 262144;

  /// < When this bit is set with IOTCON_CONNECTIVITY_IP, resources are discovered for IPv6
  static const int IOTCON_CONNECTIVITY_IPV6_ONLY = 524288;
}

/// @brief Enumeration for type of request.
/// @since_tizen 3.0
abstract class iotcon_request_type_e {
  /// < Indicates none
  static const int IOTCON_REQUEST_UNKNOWN = 0;

  /// < Indicates get method of request
  static const int IOTCON_REQUEST_GET = 1;

  /// < Indicates put method of request
  static const int IOTCON_REQUEST_PUT = 2;

  /// < Indicates post method of request
  static const int IOTCON_REQUEST_POST = 3;

  /// < Indicates delete method of request
  static const int IOTCON_REQUEST_DELETE = 4;
}

/// @brief Enumeration for type of observation.
/// @since_tizen 3.0
abstract class iotcon_observe_type_e {
  /// < Indicates no option
  static const int IOTCON_OBSERVE_NO_TYPE = 0;

  /// < Indicates action of registering observation
  static const int IOTCON_OBSERVE_REGISTER = 1;

  /// < Indicates action of unregistering observation
  static const int IOTCON_OBSERVE_DEREGISTER = 2;
}

/// @brief The remote resource handle.
